use rusqlite::{params, Connection, OptionalExtension};
use serde::{Deserialize, Serialize};
use std::path::Path;
use thiserror::Error;
use uuid::Uuid;

#[derive(Debug, Error)]
pub enum OrdersError {
    #[error("database error: {0}")]
    Db(#[from] rusqlite::Error),
    #[error("invalid input: {0}")]
    Invalid(String),
    #[error("not found: {0}")]
    NotFound(String),
    #[error("invalid order transition from {from} to {to}")]
    InvalidTransition { from: String, to: String },
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub enum OrderType { DineIn, Takeaway, Delivery }
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub enum OrderStatus { Draft, Submitted, Preparing, Ready, Served, Completed, Cancelled }
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub enum ItemStatus { Ordered, Preparing, Ready, Served, Cancelled }

impl OrderType { fn as_str(&self)->&'static str { match self {Self::DineIn=>"DINE_IN",Self::Takeaway=>"TAKEAWAY",Self::Delivery=>"DELIVERY"} } }
impl OrderStatus { fn as_str(&self)->&'static str { match self {Self::Draft=>"DRAFT",Self::Submitted=>"SUBMITTED",Self::Preparing=>"PREPARING",Self::Ready=>"READY",Self::Served=>"SERVED",Self::Completed=>"COMPLETED",Self::Cancelled=>"CANCELLED"} } }
impl ItemStatus { fn as_str(&self)->&'static str { match self {Self::Ordered=>"ORDERED",Self::Preparing=>"PREPARING",Self::Ready=>"READY",Self::Served=>"SERVED",Self::Cancelled=>"CANCELLED"} } }

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Category { pub id:String,pub name:String,pub active:bool,pub sort_order:i64,pub created_at:i64,pub updated_at:i64 }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MenuItem { pub id:String,pub category_id:String,pub name:String,pub description:Option<String>,pub station:String,pub active:bool,pub dine_in:bool,pub takeaway:bool,pub delivery:bool,pub current_price_minor:i64,pub currency:String,pub created_at:i64,pub updated_at:i64 }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Table { pub id:String,pub name:String,pub active:bool,pub created_at:i64,pub updated_at:i64 }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Order { pub id:String,pub order_number:i64,pub order_type:OrderType,pub table_id:Option<String>,pub customer_name:Option<String>,pub customer_phone:Option<String>,pub waiter_id:String,pub status:OrderStatus,pub subtotal_minor:i64,pub discount_minor:i64,pub total_minor:i64,pub currency:String,pub notes:Option<String>,pub created_at:i64,pub updated_at:i64 }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderItem { pub id:String,pub order_id:String,pub menu_item_id:String,pub name_snapshot:String,pub unit_price_minor:i64,pub quantity:i64,pub total_minor:i64,pub station:String,pub status:ItemStatus,pub notes:Option<String>,pub created_at:i64,pub updated_at:i64 }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderEvent { pub id:String,pub order_id:String,pub item_id:Option<String>,pub actor_id:String,pub event_type:String,pub reason:Option<String>,pub metadata:serde_json::Value,pub created_at:i64 }

pub struct OrdersStore { conn: Connection }
impl OrdersStore {
 pub fn open<P:AsRef<Path>>(path:P)->Result<Self,OrdersError>{ let c=Connection::open(path)?; let s=Self{conn:c}; s.migrate()?; Ok(s) }
 fn migrate(&self)->Result<(),OrdersError>{ self.conn.execute_batch("PRAGMA foreign_keys=ON; CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL); CREATE UNIQUE INDEX IF NOT EXISTS idx_categories_name ON categories(lower(name)); CREATE TABLE IF NOT EXISTS menu_items(id TEXT PRIMARY KEY,category_id TEXT NOT NULL REFERENCES categories(id),name TEXT NOT NULL,description TEXT,station TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,dine_in INTEGER NOT NULL DEFAULT 1,takeaway INTEGER NOT NULL DEFAULT 1,delivery INTEGER NOT NULL DEFAULT 0,current_price_minor INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'UGX',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS idx_menu_category ON menu_items(category_id,active); CREATE TABLE IF NOT EXISTS menu_prices(id TEXT PRIMARY KEY,menu_item_id TEXT NOT NULL REFERENCES menu_items(id),price_minor INTEGER NOT NULL,currency TEXT NOT NULL,effective_from INTEGER NOT NULL,effective_to INTEGER,created_by TEXT NOT NULL,created_at INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS idx_menu_prices_effective ON menu_prices(menu_item_id,effective_from); CREATE TABLE IF NOT EXISTS restaurant_tables(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,order_number INTEGER NOT NULL UNIQUE,order_type TEXT NOT NULL,table_id TEXT REFERENCES restaurant_tables(id),customer_name TEXT,customer_phone TEXT,waiter_id TEXT NOT NULL,status TEXT NOT NULL,subtotal_minor INTEGER NOT NULL DEFAULT 0,discount_minor INTEGER NOT NULL DEFAULT 0,total_minor INTEGER NOT NULL DEFAULT 0,currency TEXT NOT NULL DEFAULT 'UGX',notes TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status,updated_at); CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,menu_item_id TEXT NOT NULL REFERENCES menu_items(id),name_snapshot TEXT NOT NULL,unit_price_minor INTEGER NOT NULL,quantity INTEGER NOT NULL,total_minor INTEGER NOT NULL,station TEXT NOT NULL,status TEXT NOT NULL,notes TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id); CREATE TABLE IF NOT EXISTS order_events(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),item_id TEXT,actor_id TEXT NOT NULL,event_type TEXT NOT NULL,reason TEXT,metadata_json TEXT NOT NULL,created_at INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS idx_order_events_order ON order_events(order_id,created_at); CREATE TABLE IF NOT EXISTS order_number_sequence(id INTEGER PRIMARY KEY CHECK(id=1),next_number INTEGER NOT NULL); INSERT OR IGNORE INTO order_number_sequence(id,next_number) VALUES(1,1);")?; Ok(()) }
 pub fn create_category(&self,name:&str,sort_order:i64,now:i64)->Result<Category,OrdersError>{ let n=name.trim(); if n.is_empty(){return Err(OrdersError::Invalid("category name is required".into()))}; let id=Uuid::new_v4().to_string(); self.conn.execute("INSERT INTO categories(id,name,sort_order,created_at,updated_at) VALUES(?,?,?,?,?)",params![id,n,sort_order,now,now])?; Ok(Category{id,name:n.into(),active:true,sort_order,created_at:now,updated_at:now}) }
 pub fn list_categories(&self)->Result<Vec<Category>,OrdersError>{ let mut st=self.conn.prepare("SELECT id,name,active,sort_order,created_at,updated_at FROM categories ORDER BY sort_order,name")?; Ok(st.query_map([],|r|Ok(Category{id:r.get(0)?,name:r.get(1)?,active:r.get::<_,i64>(2)?!=0,sort_order:r.get(3)?,created_at:r.get(4)?,updated_at:r.get(5)?}))?.collect::<Result<Vec<_>,_>>()?) }
 pub fn create_menu_item(&self,category_id:&str,name:&str,description:Option<&str>,station:&str,price:i64,currency:&str,dine_in:bool,takeaway:bool,delivery:bool,actor:&str,now:i64)->Result<MenuItem,OrdersError>{ if price<0{return Err(OrdersError::Invalid("price cannot be negative".into()))}; if name.trim().is_empty(){return Err(OrdersError::Invalid("item name is required".into()))}; if self.conn.query_row("SELECT 1 FROM categories WHERE id=? AND active=1",params![category_id],|r|r.get::<_,i64>(0)).optional()?.is_none(){return Err(OrdersError::NotFound("category".into()))}; let id=Uuid::new_v4().to_string(); let tx=self.conn.unchecked_transaction()?; tx.execute("INSERT INTO menu_items(id,category_id,name,description,station,current_price_minor,currency,dine_in,takeaway,delivery,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",params![id,category_id,name.trim(),description,station,currency,price,dine_in as i64,takeaway as i64,delivery as i64,now,now])?; tx.execute("INSERT INTO menu_prices(id,menu_item_id,price_minor,currency,effective_from,created_by,created_at) VALUES(?,?,?,?,?,?,?)",params![Uuid::new_v4().to_string(),id,price,currency,now,actor,now])?; tx.commit()?; Ok(MenuItem{id,category_id:category_id.into(),name:name.trim().into(),description:description.map(str::to_string),station:station.into(),active:true,dine_in,takeaway,delivery,current_price_minor:price,currency:currency.into(),created_at:now,updated_at:now}) }
 pub fn list_menu(&self,category_id:Option<&str>)->Result<Vec<MenuItem>,OrdersError>{ let sql="SELECT id,category_id,name,description,station,active,dine_in,takeaway,delivery,current_price_minor,currency,created_at,updated_at FROM menu_items WHERE active=1 AND (?1 IS NULL OR category_id=?1) ORDER BY name"; let mut st=self.conn.prepare(sql)?; Ok(st.query_map(params![category_id],|r|Ok(MenuItem{id:r.get(0)?,category_id:r.get(1)?,name:r.get(2)?,description:r.get(3)?,station:r.get(4)?,active:r.get::<_,i64>(5)?!=0,dine_in:r.get::<_,i64>(6)?!=0,takeaway:r.get::<_,i64>(7)?!=0,delivery:r.get::<_,i64>(8)?!=0,current_price_minor:r.get(9)?,currency:r.get(10)?,created_at:r.get(11)?,updated_at:r.get(12)?}))?.collect::<Result<Vec<_>,_>>()?) }
 pub fn create_table(&self,name:&str,now:i64)->Result<Table,OrdersError>{ if name.trim().is_empty(){return Err(OrdersError::Invalid("table name is required".into()))}; let id=Uuid::new_v4().to_string(); self.conn.execute("INSERT INTO restaurant_tables(id,name,created_at,updated_at) VALUES(?,?,?,?)",params![id,name.trim(),now,now])?; Ok(Table{id,name:name.trim().into(),active:true,created_at:now,updated_at:now}) }
 pub fn list_tables(&self)->Result<Vec<Table>,OrdersError>{ let mut st=self.conn.prepare("SELECT id,name,active,created_at,updated_at FROM restaurant_tables WHERE active=1 ORDER BY name")?; Ok(st.query_map([],|r|Ok(Table{id:r.get(0)?,name:r.get(1)?,active:r.get::<_,i64>(2)?!=0,created_at:r.get(3)?,updated_at:r.get(4)?}))?.collect::<Result<Vec<_>,_>>()?) }
 pub fn create_order(&self,kind:OrderType,table_id:Option<&str>,customer_name:Option<&str>,customer_phone:Option<&str>,waiter_id:&str,notes:Option<&str>,currency:&str,now:i64)->Result<Order,OrdersError>{ if waiter_id.trim().is_empty(){return Err(OrdersError::Invalid("waiter identity is required".into()))}; if kind==OrderType::DineIn && table_id.is_none(){return Err(OrdersError::Invalid("dine-in orders require a table".into()))}; if let Some(t)=table_id { if self.conn.query_row("SELECT 1 FROM restaurant_tables WHERE id=? AND active=1",params![t],|r|r.get::<_,i64>(0)).optional()?.is_none(){return Err(OrdersError::NotFound("table".into()))} } let tx=self.conn.unchecked_transaction()?; let next:i64=tx.query_row("SELECT next_number FROM order_number_sequence WHERE id=1",[],|r|r.get(0))?; tx.execute("UPDATE order_number_sequence SET next_number=next_number+1 WHERE id=1",[])?; let id=Uuid::new_v4().to_string(); tx.execute("INSERT INTO orders(id,order_number,order_type,table_id,customer_name,customer_phone,waiter_id,status,currency,notes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",params![id,next,kind.as_str(),table_id,customer_name,customer_phone,waiter_id,"DRAFT",currency,notes,now,now])?; tx.execute("INSERT INTO order_events(id,order_id,actor_id,event_type,metadata_json,created_at) VALUES(?,?,?,?,?,?)",params![Uuid::new_v4().to_string(),id,waiter_id,"ORDER_CREATED","{}",now])?; tx.commit()?; Ok(Order{id,order_number:next,order_type:kind,table_id:table_id.map(str::to_string),customer_name:customer_name.map(str::to_string),customer_phone:customer_phone.map(str::to_string),waiter_id:waiter_id.into(),status:OrderStatus::Draft,subtotal_minor:0,discount_minor:0,total_minor:0,currency:currency.into(),notes:notes.map(str::to_string),created_at:now,updated_at:now}) }
 pub fn add_item(&self,order_id:&str,menu_item_id:&str,quantity:i64,notes:Option<&str>,actor:&str,now:i64)->Result<OrderItem,OrdersError>{ if quantity<=0{return Err(OrdersError::Invalid("quantity must be positive".into()))}; let o:String=self.conn.query_row("SELECT status FROM orders WHERE id=?",params![order_id],|r|r.get(0)).optional()?.ok_or_else(||OrdersError::NotFound("order".into()))?; if o!="DRAFT"&&o!="SUBMITTED"{return Err(OrdersError::Invalid("items can only be added to draft or submitted orders".into()))}; let m=(self.conn.query_row("SELECT name,current_price_minor,station FROM menu_items WHERE id=? AND active=1",params![menu_item_id],|r|Ok((r.get::<_,String>(0)?,r.get::<_,i64>(1)?,r.get::<_,String>(2)?))).optional()?).ok_or_else(||OrdersError::NotFound("menu item".into()))?; let total=m.1.checked_mul(quantity).ok_or_else(||OrdersError::Invalid("quantity total overflow".into()))?; let id=Uuid::new_v4().to_string(); let tx=self.conn.unchecked_transaction()?; tx.execute("INSERT INTO order_items(id,order_id,menu_item_id,name_snapshot,unit_price_minor,quantity,total_minor,station,status,notes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",params![id,order_id,menu_item_id,m.0,m.1,quantity,total,m.2,"ORDERED",notes,now,now])?; recalc(&tx,order_id,now)?; tx.execute("INSERT INTO order_events(id,order_id,item_id,actor_id,event_type,metadata_json,created_at) VALUES(?,?,?,?,?,?,?)",params![Uuid::new_v4().to_string(),order_id,id,actor,"ITEM_ADDED",format!(r#"{{""quantity"":{}}}"#,quantity),now])?; tx.commit()?; Ok(OrderItem{id,order_id:order_id.into(),menu_item_id:menu_item_id.into(),name_snapshot:m.0,unit_price_minor:m.1,quantity,total_minor:total,station:m.2,status:ItemStatus::Ordered,notes:notes.map(str::to_string),created_at:now,updated_at:now}) }
 pub fn cancel_item(&self,item_id:&str,actor:&str,reason:&str,now:i64)->Result<(),OrdersError>{ if reason.trim().is_empty(){return Err(OrdersError::Invalid("cancellation reason is required".into()))}; let order_id:String=self.conn.query_row("SELECT order_id FROM order_items WHERE id=?",params![item_id],|r|r.get(0)).optional()?.ok_or_else(||OrdersError::NotFound("order item".into()))?; let status:String=self.conn.query_row("SELECT status FROM order_items WHERE id=?",params![item_id],|r|r.get(0))?; if status=="CANCELLED"{return Err(OrdersError::Invalid("item is already cancelled".into()))}; let tx=self.conn.unchecked_transaction()?; tx.execute("UPDATE order_items SET status='CANCELLED',updated_at=? WHERE id=?",params![now,item_id])?; recalc(&tx,&order_id,now)?; tx.execute("INSERT INTO order_events(id,order_id,item_id,actor_id,event_type,reason,metadata_json,created_at) VALUES(?,?,?,?,?,?,?,?)",params![Uuid::new_v4().to_string(),order_id,item_id,actor,"ITEM_CANCELLED",reason,"{}",now])?; tx.commit()?; Ok(()) }
 pub fn set_discount(&self,order_id:&str,discount:i64,actor:&str,reason:&str,now:i64)->Result<Order,OrdersError>{ if discount<0{return Err(OrdersError::Invalid("discount cannot be negative".into()))}; if reason.trim().is_empty(){return Err(OrdersError::Invalid("discount reason is required".into()))}; let subtotal:i64=self.conn.query_row("SELECT subtotal_minor FROM orders WHERE id=?",params![order_id],|r|r.get(0)).optional()?.ok_or_else(||OrdersError::NotFound("order".into()))?; if discount>subtotal{return Err(OrdersError::Invalid("discount cannot exceed subtotal".into()))}; self.conn.execute("UPDATE orders SET discount_minor=?,total_minor=?,updated_at=? WHERE id=?",params![discount,subtotal-discount,now,order_id])?; self.conn.execute("INSERT INTO order_events(id,order_id,actor_id,event_type,reason,metadata_json,created_at) VALUES(?,?,?,?,?,?,?)",params![Uuid::new_v4().to_string(),order_id,actor,"DISCOUNT_SET",reason,format!(r#"{{""discount_minor"":{}}}"#,discount),now])?; self.get_order(order_id) }
 pub fn transition(&self,order_id:&str,to:OrderStatus,actor:&str,reason:Option<&str>,now:i64)->Result<Order,OrdersError>{ let from:String=self.conn.query_row("SELECT status FROM orders WHERE id=?",params![order_id],|r|r.get(0)).optional()?.ok_or_else(||OrdersError::NotFound("order".into()))?; let valid=match from.as_str(){"DRAFT"=>matches!(to,OrderStatus::Submitted|OrderStatus::Cancelled),"SUBMITTED"=>matches!(to,OrderStatus::Preparing|OrderStatus::Cancelled),"PREPARING"=>matches!(to,OrderStatus::Ready|OrderStatus::Cancelled),"READY"=>matches!(to,OrderStatus::Served),"SERVED"=>matches!(to,OrderStatus::Completed),"COMPLETED"|"CANCELLED"=>false,_=>false}; if !valid{return Err(OrdersError::InvalidTransition{from,to:to.as_str().into()})}; if matches!(to,OrderStatus::Cancelled)&&reason.map(str::trim).unwrap_or("").is_empty(){return Err(OrdersError::Invalid("cancellation reason is required".into()))}; self.conn.execute("UPDATE orders SET status=?,updated_at=? WHERE id=?",params![to.as_str(),now,order_id])?; self.conn.execute("INSERT INTO order_events(id,order_id,actor_id,event_type,reason,metadata_json,created_at) VALUES(?,?,?,?,?,?,?)",params![Uuid::new_v4().to_string(),order_id,actor,format!("STATUS_{}",to.as_str()),reason,"{}",now])?; self.get_order(order_id) }
 pub fn get_order(&self,id:&str)->Result<Order,OrdersError>{ self.conn.query_row("SELECT id,order_number,order_type,table_id,customer_name,customer_phone,waiter_id,status,subtotal_minor,discount_minor,total_minor,currency,notes,created_at,updated_at FROM orders WHERE id=?",params![id],|r|{Ok(Order{id:r.get(0)?,order_number:r.get(1)?,order_type:parse_order_type(&r.get::<_,String>(2)?),table_id:r.get(3)?,customer_name:r.get(4)?,customer_phone:r.get(5)?,waiter_id:r.get(6)?,status:parse_order_status(&r.get::<_,String>(7)?),subtotal_minor:r.get(8)?,discount_minor:r.get(9)?,total_minor:r.get(10)?,currency:r.get(11)?,notes:r.get(12)?,created_at:r.get(13)?,updated_at:r.get(14)?})}).optional()?.ok_or_else(||OrdersError::NotFound("order".into())) }
 pub fn list_orders(&self,limit:usize)->Result<Vec<Order>,OrdersError>{ let lim=limit.clamp(1,200) as i64; let mut st=self.conn.prepare("SELECT id,order_number,order_type,table_id,customer_name,customer_phone,waiter_id,status,subtotal_minor,discount_minor,total_minor,currency,notes,created_at,updated_at FROM orders ORDER BY order_number DESC LIMIT ?")?; Ok(st.query_map(params![lim],|r|Ok(Order{id:r.get(0)?,order_number:r.get(1)?,order_type:parse_order_type(&r.get::<_,String>(2)?),table_id:r.get(3)?,customer_name:r.get(4)?,customer_phone:r.get(5)?,waiter_id:r.get(6)?,status:parse_order_status(&r.get::<_,String>(7)?),subtotal_minor:r.get(8)?,discount_minor:r.get(9)?,total_minor:r.get(10)?,currency:r.get(11)?,notes:r.get(12)?,created_at:r.get(13)?,updated_at:r.get(14)?}))?.collect::<Result<Vec<_>,_>>()?) }
 pub fn list_items(&self,order_id:&str)->Result<Vec<OrderItem>,OrdersError>{ let mut st=self.conn.prepare("SELECT id,order_id,menu_item_id,name_snapshot,unit_price_minor,quantity,total_minor,station,status,notes,created_at,updated_at FROM order_items WHERE order_id=? ORDER BY created_at")?; Ok(st.query_map(params![order_id],|r|Ok(OrderItem{id:r.get(0)?,order_id:r.get(1)?,menu_item_id:r.get(2)?,name_snapshot:r.get(3)?,unit_price_minor:r.get(4)?,quantity:r.get(5)?,total_minor:r.get(6)?,station:r.get(7)?,status:parse_item_status(&r.get::<_,String>(8)?),notes:r.get(9)?,created_at:r.get(10)?,updated_at:r.get(11)?}))?.collect::<Result<Vec<_>,_>>()?) }
 pub fn list_events(&self,order_id:&str)->Result<Vec<OrderEvent>,OrdersError>{ let mut st=self.conn.prepare("SELECT id,order_id,item_id,actor_id,event_type,reason,metadata_json,created_at FROM order_events WHERE order_id=? ORDER BY created_at,id")?; Ok(st.query_map(params![order_id],|r|Ok(OrderEvent{id:r.get(0)?,order_id:r.get(1)?,item_id:r.get(2)?,actor_id:r.get(3)?,event_type:r.get(4)?,reason:r.get(5)?,metadata:serde_json::from_str(&r.get::<_,String>(6)?).unwrap_or(serde_json::Value::Null),created_at:r.get(7)?}))?.collect::<Result<Vec<_>,_>>()?) }
}
fn recalc(tx:&rusqlite::Transaction<'_>,order_id:&str,now:i64)->Result<(),OrdersError>{ let subtotal:i64=tx.query_row("SELECT COALESCE(SUM(total_minor),0) FROM order_items WHERE order_id=? AND status<>'CANCELLED'",params![order_id],|r|r.get(0))?; let discount:i64=tx.query_row("SELECT discount_minor FROM orders WHERE id=?",params![order_id],|r|r.get(0))?; let total=subtotal.checked_sub(discount).ok_or_else(||OrdersError::Invalid("discount exceeds subtotal".into()))?; tx.execute("UPDATE orders SET subtotal_minor=?,total_minor=?,updated_at=? WHERE id=?",params![subtotal,total,now,order_id])?; Ok(()) }
fn parse_order_type(v:&str)->OrderType{match v{"TAKEAWAY"=>OrderType::Takeaway,"DELIVERY"=>OrderType::Delivery,_=>OrderType::DineIn}}
fn parse_order_status(v:&str)->OrderStatus{match v{"SUBMITTED"=>OrderStatus::Submitted,"PREPARING"=>OrderStatus::Preparing,"READY"=>OrderStatus::Ready,"SERVED"=>OrderStatus::Served,"COMPLETED"=>OrderStatus::Completed,"CANCELLED"=>OrderStatus::Cancelled,_=>OrderStatus::Draft}}
fn parse_item_status(v:&str)->ItemStatus{match v{"PREPARING"=>ItemStatus::Preparing,"READY"=>ItemStatus::Ready,"SERVED"=>ItemStatus::Served,"CANCELLED"=>ItemStatus::Cancelled,_=>ItemStatus::Ordered}}
